// Renders the recorded run in data/demo-run.js (generated by tools/demo.py from demo-workspace/)
// and the caption cues in data/replay-captions.js (generated with the video). Nothing here is
// hard-coded run data; every string from the run is HTML-escaped before insertion.
(function () {
  "use strict";
  const D = window.DEMO_RUN;
  const CAP = window.REPLAY_CAPTIONS || null;
  const $ = (id) => document.getElementById(id);
  if (!D) {
    $("main").innerHTML = '<p class="wrap section">Missing <code>data/demo-run.js</code>. Run <code>python tools/demo.py run</code>.</p>';
    return;
  }
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  const links = (html) => html.replace(/\[\[([^\]]+)\]\]/g, '<span class="wl">[[$1]]</span>');
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const run = D.run;
  const isMock = run.mode === "mock";
  const pages = D.after.pages;
  const title = (id) => (pages[id] || D.before.pages[id] || {}).title || id;
  const changes = D.changes;
  const approved = changes.filter((c) => c.decision === "approve");
  const edited = approved.filter((c) => c.edited_by_reviewer);
  const rejected = changes.filter((c) => c.decision === "reject");
  const g = D.graph;
  const va = D.after.validation;
  const con = D.proposal.contradictions[0];
  const words = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight"];
  const num = (n) => words[n] || String(n);

  // ------------------------------------------------------------ header + hero
  $("mode-pill").textContent = isMock ? "MOCK RUN" : "LLM RUN";
  $("mode-pill").setAttribute("aria-label", (isMock ? "Mock run" : "LLM run") + " — what is real in this demo");
  $("disclosure").innerHTML = isMock
    ? `<span class="tag-mock">MOCK RUN</span><span>The proposal in this recorded run comes from a hand-authored fixture, not a language model. Everything after it — policy checks, human review, writes and validation — is the real pipeline. <a href="#whats-real">What’s real?</a></span>`
    : `<span class="tag-mock">LLM RUN</span><span>${esc(run.mode_label)}. <a href="#whats-real">Details</a></span>`;

  const pairs = (edges) => new Set(edges.map(([a, b]) => [a, b].sort().join("|"))).size;
  const stats = [
    [`${Object.keys(D.before.pages).length} → <em>${Object.keys(pages).length}</em>`, "pages"],
    [`${pairs(g.before.edges)} → <em>${pairs(g.after.edges)}</em>`, "linked page pairs"],
    [`${changes.length}`, "changes proposed"],
    [`${approved.length}<small style="font-size:.9rem;color:var(--muted)"> (${edited.length} edited)</small>`, "approved by a human"],
    [`${rejected.length}`, "rejected by a human"],
  ];
  $("stats").innerHTML = stats.map(([v, l]) => `<div><dd>${v}</dd><dt>${esc(l)}</dt></div>`).join("");
  $("hero-caption").textContent = "graph of the wiki after the recorded run";

  // --------------------------------------------------------------- layout
  const pairKey = (a, b) => [a, b].sort().join("|");
  const allPairs = new Map();
  for (const [a, b] of g.after.edges.concat(g.rejected_edges)) allPairs.set(pairKey(a, b), [a, b]);
  const layoutNodes = (() => { // small deterministic force layout, normalised to 0..1
    const ns = g.after.nodes.map((n, i, all) => ({ ...n, x: Math.cos(2 * Math.PI * i / all.length) * 200, y: Math.sin(2 * Math.PI * i / all.length) * 150, vx: 0, vy: 0 }));
    const by = Object.fromEntries(ns.map((n) => [n.id, n]));
    for (let it = 0; it < 600; it++) {
      for (const p of ns) for (const q of ns) {
        if (p === q) continue;
        const dx = p.x - q.x, dy = p.y - q.y, d2 = Math.max(dx * dx + dy * dy, 1);
        p.vx += (dx / Math.sqrt(d2)) * 9000 / d2; p.vy += (dy / Math.sqrt(d2)) * 9000 / d2;
      }
      for (const [a, b] of allPairs.values()) {
        const p = by[a], q = by[b], dx = q.x - p.x, dy = q.y - p.y, d = Math.hypot(dx, dy) || 1, f = (d - 170) * 0.01;
        p.vx += (dx / d) * f; p.vy += (dy / d) * f; q.vx -= (dx / d) * f; q.vy -= (dy / d) * f;
      }
      for (const p of ns) { p.vx -= p.x * 0.004; p.vy -= p.y * 0.006; p.x += p.vx * 0.5; p.y += p.vy * 0.5; p.vx *= 0.6; p.vy *= 0.6; }
    }
    const xs = ns.map((n) => n.x), ys = ns.map((n) => n.y);
    const [x0, x1, y0, y1] = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
    for (const n of ns) { n.u = (n.x - x0) / (x1 - x0 || 1); n.v = (n.y - y0) / (y1 - y0 || 1); }
    return by;
  })();
  const COLORS = { created: "#22D3EE", updated: "#8B5CF6", source: "#3B82F6", concept: "#7A8CA8" };
  const nodeColor = (n, withState) => withState && g.touched[n.id] ? COLORS[g.touched[n.id]] : n.type === "source" ? COLORS.source : COLORS.concept;

  // ---------------------------------------------------------- hero canvas
  (function heroCanvas() {
    const cv = $("hero-canvas");
    const ctx = cv.getContext("2d");
    const nodes = Object.values(layoutNodes);
    const beforeKeys = new Set(g.before.edges.map(([p, q]) => pairKey(p, q)));
    const rejectedKeys = new Set(g.rejected_edges.map(([p, q]) => pairKey(p, q)));
    let W = 0, H = 0, running = false;
    const t0 = performance.now();
    const rnd = (() => { let s = 7; return () => (s = (s * 16807) % 2147483647) / 2147483647; })();
    const frags = Array.from({ length: 110 }, () => ({
      n: nodes[Math.floor(rnd() * nodes.length)], x: rnd(), y: rnd(), d: rnd() * 1.4, a: rnd() * 6.28, o: 10 + rnd() * 26,
      c: rnd() > 0.5 ? "34,211,238" : "139,92,246",
    }));
    const pos = (n) => [W * (0.12 + 0.76 * n.u), H * (0.16 + 0.62 * n.v)];
    const clamp = (x) => Math.min(1, Math.max(0, x));
    const ease = (x) => { x = clamp(x); return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; };
    function resize() {
      const r = cv.getBoundingClientRect(), dpr = Math.min(window.devicePixelRatio || 1, 2);
      W = r.width; H = r.height; cv.width = Math.max(1, W * dpr); cv.height = Math.max(1, H * dpr); ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }
    function frame(now) {
      const t = reduceMotion ? 99 : (now - t0) / 1000;
      ctx.clearRect(0, 0, W, H);
      const edgesIn = clamp((t - 2.6) / 1.2);
      for (const [key, [a, b]] of allPairs) {
        const rej = rejectedKeys.has(key);
        if (rej && edgesIn < 1) continue;
        const [ax, ay] = pos(layoutNodes[a]), [bx, by] = pos(layoutNodes[b]), isNew = !beforeKeys.has(key);
        ctx.strokeStyle = rej ? "rgba(248,113,113,.45)" : isNew ? `rgba(34,211,238,${0.55 * edgesIn})` : `rgba(51,80,122,${0.9 * edgesIn})`;
        ctx.lineWidth = isNew ? 1.8 : 1.2;
        ctx.setLineDash(rej ? [5, 5] : []);
        ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
      }
      ctx.setLineDash([]);
      for (const f of frags) {
        const k = ease((t - f.d) / 2.4), [nx, ny] = pos(f.n);
        const orbit = f.o * (1 - clamp((t - 3.2) / 1.4) * 0.75);
        const ox = nx + Math.cos(f.a + t * 0.5) * orbit, oy = ny + Math.sin(f.a + t * 0.5) * orbit;
        ctx.fillStyle = `rgba(${f.c},${0.35 + 0.35 * k})`;
        ctx.beginPath(); ctx.arc(f.x * W + (ox - f.x * W) * k, f.y * H + (oy - f.y * H) * k, 1.6, 0, 6.283); ctx.fill();
      }
      const nodesIn = clamp((t - 2.2) / 1.0);
      for (const n of nodes) {
        const [x, y] = pos(n), col = nodeColor(n, true), r = (n.type === "source" ? 7 : 9) * nodesIn;
        if (r <= 0) continue;
        const pulse = g.touched[n.id] ? 0.5 + 0.5 * Math.sin(t * 2 + n.u * 6) : 0, R = 34 + 8 * pulse;
        const grad = ctx.createRadialGradient(x, y, 0, x, y, R);
        grad.addColorStop(0, col + (g.touched[n.id] ? "66" : "33")); grad.addColorStop(1, col + "00");
        ctx.fillStyle = grad; ctx.beginPath(); ctx.arc(x, y, R, 0, 6.283); ctx.fill();
        ctx.fillStyle = col; ctx.beginPath(); ctx.arc(x, y, r, 0, 6.283); ctx.fill();
      }
      if (running && !reduceMotion) requestAnimationFrame(frame);
    }
    resize();
    window.addEventListener("resize", () => { resize(); if (!running || reduceMotion) frame(performance.now()); });
    new IntersectionObserver(([e]) => { // animate only while visible
      const was = running; running = e.isIntersecting;
      if (running && !was) requestAnimationFrame(frame);
    }).observe(cv);
    frame(performance.now());
  })();

  // ---------------------------------------------------------------- video
  const MUSIC = CAP && CAP.audio;
  $("video-lede").textContent = "A replay rendered frame by frame from the artifacts of this run — not a screen recording. "
    + (isMock ? "The proposal it shows is the hand-authored fixture and the decisions come from a pre-recorded file. " : "")
    + "Captions are part of the picture, so it works with the sound off. "
    + (MUSIC ? "Background music only; no narration." : "There is no audio track.");
  if (MUSIC) {
    const credit = `Music: <a href="${esc(MUSIC.source_url)}" rel="noopener" target="_blank">“${esc(MUSIC.title)}”</a> by ${esc(MUSIC.artist)} (${esc(MUSIC.publisher)}), `
      + `licensed under <a href="${esc(MUSIC.license_url)}" rel="noopener" target="_blank">${esc(MUSIC.license)}</a>. ${esc(MUSIC.changes)}`;
    $("music-credit").innerHTML = credit;
    $("footer-music").innerHTML = credit;
  } else {
    $("music-credit").hidden = true;
  }
  if (CAP) {
    $("video-h").textContent = `The run in ${Math.round(CAP.duration_s)} seconds`;
    const fmt = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
    $("transcript-cues").innerHTML = CAP.cues.map((c) => `<li><time>${fmt(c.start)}</time>${esc(c.text)}</li>`).join("");
  }

  // ---------------------------------------------------------------- story
  if (con) {
    $("story-before").innerHTML = `<b>${esc(title(con.page))}</b>: “${esc(con.existing_claim)}”`;
    $("story-evidence").textContent = con.new_evidence;
  }
  const decisionLine = (c) => `<b>${esc(c.change_id)}</b> ${esc(c.note || "")}`;
  $("story-decision").innerHTML =
    `Approved ${num(approved.length - edited.length)} change(s) as proposed` +
    (edited.length ? `, corrected ${num(edited.length)} before approving (${edited.map(decisionLine).join("; ")})` : "") +
    (rejected.length ? `, and rejected ${num(rejected.length)} (${rejected.map(decisionLine).join("; ")})` : "") + ".";

  // ----------------------------------------------------------------- flow
  const STAGES = {
    read_source: ["Read the raw source", "ingest"], inspect_wiki: ["Load the existing wiki as context", "ingest"],
    propose: [isMock ? "Get proposal — mock fixture" : "Get proposal — LLM", "ingest"],
    check_proposal: ["Schema and policy checks", "ingest"], stage: ["Stage pages and diffs", "ingest"],
    review: ["Decide every change", "review"], preflight: ["Validate the candidate wiki", "apply"],
    write: ["Write approved pages", "apply"], index: ["Rebuild the index", "apply"],
    log: ["Append to the log", "apply"], validate: ["Validate the wiki", "apply"],
  };
  const PHASES = [
    ["ingest", "1 · Ingest", "python -m brain ingest", "Reads, proposes and stages. Writes nothing to the wiki."],
    ["review", "2 · Human review", "python -m brain review", isMock ? "Approve, edit or reject each change — here from a pre-recorded decisions file." : "Approve, edit or reject each change."],
    ["apply", "3 · Apply", "python -m brain apply", "Only approved changes; refuses stale or invalid results."],
  ];
  $("phases").innerHTML = PHASES.map(([key, name, cmd, what]) => {
    const evs = run.events.filter((e) => (STAGES[e.stage] || [e.stage, "apply"])[1] === key);
    return `<section class="phase${key === "review" ? " human" : ""}" aria-label="${esc(name)}"><header><h3>${esc(name)}</h3><code>${esc(cmd)}</code></header>
      <p class="what">${esc(what)}</p>
      ${evs.map((e) => `<div class="event ${esc(e.status)}"><i aria-hidden="true"></i><div><b>${esc((STAGES[e.stage] || [e.stage])[0])}${e.status !== "ok" ? ` — ${esc(e.status)}` : ""}</b><span>${esc(e.detail)}</span></div></div>`).join("")}</section>`;
  }).join("");

  // --------------------------------------------------------------- source
  $("source-path").textContent = D.source.path;
  $("source-hash").textContent = "sha256 " + D.source.sha256.slice(0, 12) + "…";
  (function renderSource() {
    const text = D.source.text;
    const phrases = D.source.flags.map((f) => (f.match(/'(.+)'$/) || [])[1]).filter(Boolean);
    const ranges = [], re = /<!--[\s\S]*?-->/g;
    let m;
    while ((m = re.exec(text))) if (phrases.some((p) => m[0].includes(p))) ranges.push([m.index, m.index + m[0].length]);
    let html = "", pos = 0;
    for (const [a, b] of ranges) { html += esc(text.slice(pos, a)) + `<mark class="inject">${esc(text.slice(a, b))}</mark>`; pos = b; }
    $("source-text").innerHTML = html + esc(text.slice(pos));
    const notes = D.proposal.security_notes.map((n) => (isMock ? "Fixture note: " : "Model note: ") + n).concat(D.source.flags.map((f) => "Engine: " + f));
    $("source-flags").innerHTML = notes.map((n) => `<li>${esc(n)}</li>`).join("");
  })();

  const beforeIds = Object.keys(D.before.pages);
  function showBefore(id) {
    const p = D.before.pages[id];
    $("before-page-path").textContent = p.path;
    $("before-page-status").textContent = p.status;
    $("before-page-text").innerHTML = links(esc(p.text));
    document.querySelectorAll("#before-pages button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.id === id)));
  }
  $("before-pages").innerHTML = beforeIds.map((id) => `<button type="button" data-id="${esc(id)}" aria-pressed="false">${esc(id)}</button>`).join("");
  $("before-pages").addEventListener("click", (e) => { const b = e.target.closest("button"); if (b) showBefore(b.dataset.id); });
  showBefore(con && D.before.pages[con.page] ? con.page : beforeIds[0]);

  // ------------------------------------------------------------ line diff
  function lineDiff(a, b) {
    const x = a.replace(/\n$/, "").split("\n"), y = b.replace(/\n$/, "").split("\n");
    const n = x.length, m = y.length, L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1));
    for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) L[i][j] = x[i] === y[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1]);
    const out = []; let i = 0, j = 0;
    while (i < n && j < m) {
      if (x[i] === y[j]) { out.push([" ", x[i]]); i++; j++; } else if (L[i + 1][j] >= L[i][j + 1]) out.push(["-", x[i++]]); else out.push(["+", y[j++]]);
    }
    while (i < n) out.push(["-", x[i++]]);
    while (j < m) out.push(["+", y[j++]]);
    return out;
  }
  const renderUnified = (ops) => ops.map(([op, line]) => `<span class="${op === "+" ? "add" : op === "-" ? "del" : ""}">${esc(op + " " + line)}</span>`).join("");
  const renderGitDiff = (diff) => diff.replace(/\n$/, "").split("\n").map((l) => {
    const cls = l.startsWith("+++") || l.startsWith("---") ? "meta" : l.startsWith("@@") ? "hunk" : l.startsWith("+") ? "add" : l.startsWith("-") ? "del" : "";
    return `<span class="${cls}">${esc(l)}</span>`;
  }).join("");

  // --------------------------------------------------------------- review
  $("interpretation").innerHTML = `<b>${isMock ? "Fixture’s interpretation" : "Model’s interpretation"}:</b> ${esc(D.proposal.interpretation)}`;
  if (con) {
    $("contradiction").innerHTML =
      `<div class="was"><b>Existing claim · ${esc(con.page)}</b>${esc(con.existing_claim)}</div>` +
      `<div class="ev"><b>New evidence</b>${esc(con.new_evidence)}</div>` +
      `<div class="now"><b>Proposed resolution</b>${esc(con.proposed_resolution)}</div>`;
  }
  $("changes").innerHTML = changes.map((c) => {
    const kind = c.decision === "reject" ? "reject" : c.edited_by_reviewer ? "edited" : "approve";
    const label = { reject: "REJECTED", edited: "EDITED + APPROVED", approve: "APPROVED" }[kind];
    const editBlock = c.edited_by_reviewer
      ? `<p class="sub-h">Reviewer’s correction (proposed → written)</p><pre class="diff">${renderUnified(lineDiff(c.proposed_text, c.final_text).filter(([op]) => op !== " "))}</pre>` : "";
    return `<details class="change ${kind}"${kind !== "approve" ? " open" : ""}>
      <summary><span class="cid">${esc(c.change_id)}</span>
        <span class="what"><b>${esc(c.action)} ${esc(c.page_id)}</b><small>${esc(c.rationale)}</small></span>
        <span class="verdict ${kind}">${label}</span></summary>
      <div class="change-body">${c.note ? `<p class="note"><b>Reviewer:</b> ${esc(c.note)}</p>` : ""}${editBlock}
        <p class="sub-h">Proposed diff</p><pre class="diff" tabindex="0">${renderGitDiff(c.diff)}</pre></div></details>`;
  }).join("");

  // --------------------------------------------------------- before/after
  let baView = "side";
  $("ba-page").innerHTML = approved.map((c) => `<option value="${esc(c.page_id)}">${esc(c.page_id)}${D.before.pages[c.page_id] ? "" : " (new)"}</option>`).join("");
  if (con && approved.some((c) => c.page_id === con.page)) $("ba-page").value = con.page;
  function renderBA() {
    const id = $("ba-page").value, before = D.before.pages[id] ? D.before.pages[id].text : "", after = pages[id].text;
    const ops = lineDiff(before, after), box = $("ba");
    if (baView === "diff") {
      box.className = "ba single";
      box.innerHTML = `<div class="file"><div class="file-head"><span>${esc(pages[id].path)}</span><span>unified diff</span></div><pre class="file-body" tabindex="0">${renderUnified(ops)}</pre></div>`;
      return;
    }
    box.className = "ba";
    const side = (skip, mark, cls) => ops.filter(([op]) => op !== skip).map(([op, l]) => `<span class="${op === mark ? cls : ""}">${links(esc(l)) || " "}</span>`).join("");
    box.innerHTML =
      `<div class="file"><div class="file-head"><span>before</span><span class="tag">${esc(D.before.pages[id] ? D.before.pages[id].status : "did not exist")}</span></div><pre class="file-body" tabindex="0">${before ? side("+", "-", "del") : "(page did not exist)"}</pre></div>` +
      `<div class="file"><div class="file-head"><span>after</span><span class="tag">${esc(pages[id].status)}</span></div><pre class="file-body" tabindex="0">${side("-", "+", "add")}</pre></div>`;
  }
  $("ba-page").addEventListener("change", renderBA);
  document.querySelectorAll("[data-view]").forEach((b) => b.addEventListener("click", () => {
    baView = b.dataset.view;
    document.querySelectorAll("[data-view]").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
    renderBA();
  }));
  renderBA();

  // ----------------------------------------------------------------- graph
  const GW = 900, GH = 520, PAD = 80;
  const gpos = (id) => [PAD + layoutNodes[id].u * (GW - 2 * PAD), PAD - 16 + layoutNodes[id].v * (GH - 2 * PAD)];
  const byState = (s) => Object.keys(g.touched).filter((k) => g.touched[k] === s).join(", ") || "none";
  function drawGraph(which) {
    const beforeNodes = new Set(g.before.nodes.map((n) => n.id));
    const beforePairs = new Set(g.before.edges.map(([a, b]) => pairKey(a, b)));
    const afterPairs = new Set(g.after.edges.map(([a, b]) => pairKey(a, b)));
    let svg = "";
    for (const [key, [a, b]] of allPairs) {
      const [x1, y1] = gpos(a), [x2, y2] = gpos(b);
      let cls = "edge";
      if (which === "before") { if (!beforePairs.has(key)) continue; }
      else if (!afterPairs.has(key)) cls += " rejected";
      else if (!beforePairs.has(key)) cls += " added";
      svg += `<line class="${cls}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"><title>${esc(a)} ↔ ${esc(b)}</title></line>`;
    }
    for (const n of Object.values(layoutNodes)) {
      const exists = which === "after" || beforeNodes.has(n.id);
      const [x, y] = gpos(n.id);
      const status = which === "before" ? (D.before.pages[n.id] || {}).status : n.status;
      const state = which === "after" ? g.touched[n.id] : null;
      const col = nodeColor(n, which === "after"), r = n.type === "source" ? 12 : 16;
      const sub = [state, status === "needs-review" ? "needs review" : null, which === "after" && g.rejected_pages.includes(n.id) ? "change rejected" : null].filter(Boolean).join(" · ");
      const label = n.title.replace(/^SAMPLE: /, "");
      svg += `<g class="node${exists ? "" : " fade"}" transform="translate(${x},${y})"><title>${esc(n.id)}</title>` +
        (state ? `<circle class="halo" r="${r + 12}" fill="${col}"></circle>` : "") +
        (status === "needs-review" && which === "after" ? `<circle r="${r + 6}" fill="none" stroke="#F59E0B" stroke-width="2"></circle>` : "") +
        `<circle class="core" r="${r}" fill="${col}"></circle>` +
        `<text y="${r + 19}" text-anchor="middle">${esc(label.length > 40 ? label.slice(0, 38) + "…" : label)}</text>` +
        (sub ? `<text class="sub" y="${r + 34}" text-anchor="middle">${esc(sub)}</text>` : "") + `</g>`;
    }
    const desc = which === "before"
      ? `Before the ingest: ${g.before.nodes.length} pages and ${pairs(g.before.edges)} linked page pairs.`
      : `After the ingest: ${g.after.nodes.length} pages and ${pairs(g.after.edges)} linked page pairs. Created: ${byState("created")}. Updated: ${byState("updated")}. Rejected proposed links: ${g.rejected_edges.length}.`;
    $("graph-svg").innerHTML = `<desc id="graph-desc">${esc(desc)}</desc>` + svg;
    document.querySelectorAll("[data-graph]").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.graph === which)));
  }
  document.querySelectorAll("[data-graph]").forEach((b) => b.addEventListener("click", () => drawGraph(b.dataset.graph)));
  drawGraph("after");

  // ----------------------------------------------------------------- audit
  const vcard = (label, v) => `<div class="vcard"><h4>${esc(label)} <span class="${v.ok ? "pass" : "fail"}">${v.ok ? "PASSED" : "FAILED"}</span></h4>
    <dl><dt>pages</dt><dd>${v.stats.pages}</dd><dt>concepts / sources</dt><dd>${v.stats.concepts} / ${v.stats.sources}</dd>
    <dt>wikilinks</dt><dd>${v.stats.links}</dd><dt>errors</dt><dd>${v.errors.length}</dd><dt>warnings</dt><dd>${v.warnings.length}</dd></dl></div>`;
  $("validation").innerHTML = `<div class="vgrid">${vcard("Before", D.before.validation)}${vcard("After", va)}</div>` +
    `<ul class="warnings">${va.warnings.map((w) => `<li>warning · ${esc(w)}</li>`).join("")}${va.errors.map((e) => `<li>error · ${esc(e)}</li>`).join("")}</ul>` +
    `<p class="checks">Checks: required fields · id/file/type consistency · every [[link]] resolves · cited sources exist · raw sha256 matches raw/ · no duplicate ids or titles · index up to date.</p>`;
  const log = D.after.log;
  $("log-entry").innerHTML = links(esc(log.slice(log.lastIndexOf("\n## [") + 1)));
  $("transcript").innerHTML = D.transcript.map((s, i) => `<details${i === 2 || /Repeat/.test(s.label) ? " open" : ""}>
    <summary><span class="lbl">${esc(s.label)}</span><span class="cmd">${esc(s.command)}</span></summary>
    <pre>${esc(s.output).replace(/^(\[MOCK MODE\].*)$/gm, '<span class="mock">$1</span>')}</pre></details>`).join("");

  // ----------------------------------------------------------- what's real
  const REAL = [
    ["genuine", "Pipeline code", "Parsing, policy checks, staging, diffs, review recording, preflight validation, writes, index, log and final validation — executed through the real CLI."],
    isMock ? ["mock", "Proposal content", "A hand-authored fixture shaped like a model response. It includes two deliberate overreaches for the reviewer to catch."]
           : ["genuine", "Proposal content", run.mode_label],
    isMock ? ["scripted", "Reviewer decisions", "Supplied from a pre-recorded decisions file. The interactive review prompt exists but was not used for this recording."]
           : ["genuine", "Reviewer decisions", D.honesty.reviewer],
    ["untested", "Live LLM path", "Implemented with the official Anthropic SDK and tested with a stubbed client. Not run against the live API for this demo."],
    ["replay", "Video", "Rendered frame by frame from this run’s artifacts. Not a screen recording; captions burned in; "
      + (CAP && CAP.audio ? `licensed background music (“${CAP.audio.title}”, ${CAP.audio.artist}, ${CAP.audio.license}); no narration.` : "no audio track.")],
    ["fictional", "Sample scenario", "Fictional teaching material labelled SAMPLE. It makes no claims about real systems or projects."],
  ];
  $("real-grid").innerHTML = REAL.map(([lvl, name, text]) => `<div class="real"><span class="lvl ${lvl}">${lvl.toUpperCase()}</span><b>${esc(name)}</b><p>${esc(text)}</p></div>`).join("");

  $("footer-note").textContent = `Data: site/data/demo-run.js — generated from demo-workspace/, recorded ${run.mode} run ${run.run_id}.`;
  window.addEventListener("load", () => {
    const target = location.hash && document.getElementById(location.hash.slice(1));
    if (target) requestAnimationFrame(() => target.scrollIntoView());
  });
})();
